const now = new Date();
const timeMin = new Date(now.getTime() + 60*60*1000).toISOString();
const timeMax = new Date(now.getTime() + 7*24*60*60*1000).toISOString();
return [{ json: { timeMin, timeMax } }];

const { DateTime } = require('luxon');
const busy = ($json.calendars && $json.calendars.primary && $json.calendars.primary.busy) || [];
const TZ = 'Europe/Warsaw';
const busyIv = busy.map(b => ({ s: DateTime.fromISO(b.start), e: DateTime.fromISO(b.end) }));
const SLOT = 30, D0 = 9, D1 = 19;
function free(dt){ const end = dt.plus({minutes:SLOT});
  return dt > DateTime.now().plus({hours:1}) && !busyIv.some(b => dt < b.e && end > b.s); }
const PL = {1:'w poniedzialek',2:'we wtorek',3:'w srode',4:'w czwartek',5:'w piatek'};
const out = [];
let base = DateTime.now().setZone(TZ).startOf('day');
for (let d=0; d<7 && out.length<3; d++){
  const day = base.plus({days:d}); if (day.weekday > 5) continue;
  for (let h=D0; h<D1 && out.length<3; h++){
    for (let m=0; m<60; m+=SLOT){
      const dt = day.set({hour:h,minute:m,second:0,millisecond:0});
      if (free(dt)){
        const rel = d===0?'dzisiaj':(d===1?'jutro':PL[day.weekday]);
        out.push({ when_iso: dt.toISO(), spoken: rel+' o '+String(h).padStart(2,'0')+':'+String(m).padStart(2,'0') });
      }
    }
  }
}
const spoken = out.length
  ? 'Mam wolne terminy: '+out.map(o=>o.spoken).join(', ')+'. Ktory Panu lub Pani odpowiada?'
  : 'Niestety nie widze wolnych terminow w tym tygodniu.';
return [{ json: { ok: out.length>0, slots: out, spoken } }];

const { DateTime } = require('luxon');
const a = $json.body || $json;
if (!a.when_iso) throw new Error('Brak when_iso');
const start = DateTime.fromISO(a.when_iso, { zone: 'Europe/Warsaw' });
const end = start.plus({ minutes: 30 });
const hasEmail = !!(a.email && a.email.includes('@'));
return [{ json: {
  summary: 'Konsultacja STRONEVO - ' + (a.firstName || 'Klient'),
  description: 'Rozmowa umowiona przez Ade. Temat: ' + (a.branza || 'automatyzacje') + '. Lead: ' + (a.lead_id || '-'),
  attendeeEmail: hasEmail ? a.email : '',
  hasEmail,
  startISO: start.toISO(),
  endISO: end.toISO(),
  requestId: 'ada-' + (a.lead_id || Date.now()) + '-' + Math.floor(Math.random()*1e6),
  whenSpoken: start.setLocale('pl').toFormat("cccc d LLLL 'o' HH:mm")
} }];

const ev = $json;
let meet = ev.hangoutLink || '';
if (!meet && ev.conferenceData && ev.conferenceData.entryPoints){
  const v = ev.conferenceData.entryPoints.find(e => e.entryPointType === 'video');
  meet = v ? v.uri : '';
}
return [{ json: {
  ok: !!ev.id, meet,
  when: $('Prep event').item.json.whenSpoken,
  eventId: ev.id || null, htmlLink: ev.htmlLink || ''
} }];
